/*getPunchoutItemSeq*/

SELECT TO_CHAR(MAX(ITEM_SEQ),'FM000000') FROM DOOSCART      
 WHERE BUYER          				= #{BUYER}                
   AND USER_ID        				= #{USER_ID}         
   AND USE_FLAG       				= #{USE_FLAG}
   AND BUYER_ITEM_NO       		= #{BUYER_ITEM_NO}      
   AND AGENT       					= #{AGENT}           
   AND CONTRACT_NO    			= #{CONTRACT_NO}                
   AND CONTRACT_SEQ   			= #{CONTRACT_SEQ}

mapper.update:

		/*updateBuyerMdCmFolderCode*/
		   UPDATE DOOSCART         
               SET ITEM_SEQ = #{FOLDER_CODE}    
             WHERE BUYER = #{BUYER}        
               AND USER_ID = #{USER_ID}       
               AND USE_FLAG = #{USE_FLAG}     
               AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}
               AND CONTRACT_NO = #{CONTRACT_NO}
               AND CONTRACT_SEQ =#{CONTRACT_SEQ}
               AND AGENT = #{AGENT}   
               AND BYIT_COMORG_CODE =#{BYIT_COMORG_CODE}


		/*updateBuyerMdCmFolderName*/
             UPDATE ICOMUSCA 
                SET CATEG_NAME =  #{FOLDER_3},
                    CATEG_PATH = '전체 > '||#{FOLDER_3} , 
                    CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),  
                    CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')   
              WHERE BUYER = #{BUYER}
                AND USER_ID = #{USER_ID}
                AND CATEG_ID = #{FOLDER_2}

