/*selectBuyerMdCmDeletePunchOutSearchList*/ SELECT B.IMGFILE_NAME IMGFILE_NAME, B.IMGFILE_DIR IMGFILE_DIR, Q.BUYER_ITEM_NO BUYER_ITEM_NO, B.DESCRIPTION_LOC DESCRIPTION, B.SPECIFICATION SPECIFICATION, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = Q.ORIGIN_CODE) ORIGIN_TEXT, Q.MAKER_NAME MAKER_NAME, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = Q.AGENT) AGENT_NAME, Q.UNIT_MEASURE UNIT_MEASURE, Q.UNIT_PRICE UNIT_PRICE, '0' TARGET_QTY, Q.AGENT AGENT, Q.CHANGE_DATE REG_DATE, B.CATEGORY_NO CATEG_ID, Q.CONTRACT_NO CONTRACT_NO, Q.CONTRACT_SEQ CONTRACT_SEQ, Q.BELOW_COMORG_CODE BYCA_COMORG_CODE, Q.ITEM_NO AS DOOSAN_BUYER_ITEM_NO, DECODE(B.PRODUCT_CLOSE_FLAG,'Y','단종','삭제') PRODUCT_CLOSE_FLAG, DECODE(Q.ITEM_NO,NULL,'비재고','재고가능') AS GUBUN FROM ICOMCQDT Q, ICOMBYIT B WHERE Q.BUYER =#{st_buyer} AND B.BUYER = Q.BUYER AND B.BUYER_ITEM_NO = Q.BUYER_ITEM_NO AND B.CATEGORY_NO NOT IN ('P-A-07-04-ZZZZ','P-H-14-17-0001') AND (B.PRODUCT_CLOSE_FLAG = 'Y' OR B.STATUS = 'D' OR Q.STATUS = 'D')
AND (UPPER(Q.BUYER_ITEM_NO) LIKE '%'||UPPER(#{st_buyer_item_no})||'%' OR UPPER(Q.BUYER_ITEM_NO) LIKE '%'||UPPER(#{st_buyer_item_no})||'%')
AND UPPER(Q.DESCRIPTION) LIKE '%'||UPPER(#{st_description})||'%'
AND UPPER(Q.SPECIFICATION) LIKE '%'||UPPER(#{st_specification})||'%'
ORDER BY ${st_sort_column} ${st_sort_flag}
ORDER BY Q.BUYER_ITEM_NO, Q.DESCRIPTION
